shellCommands.command:
cat > src/smoke.test.tsx <<'EOF'
import {renderToString} from 'react-dom/server';
import {describe, expect, it} from 'vitest';
import {ThemeProvider} from '@gravity-ui/uikit';
import {App} from './App';

describe('smoke', () => {
  it('renders the dashboard shell and orders table', () => {
    const html = renderToString(
      <ThemeProvider theme="light">
        <App />
      </ThemeProvider>,
    );
    for (const text of ['Главная', 'Пользователи', 'Заказы', 'Настройки', 'ORD-1040', 'Сумма', 'Статус']) {
      expect(html).toContain(text);
    }
  });
});
EOF
timeout 300 npx vitest run src/smoke.test.tsx 2>&1 | grep -v "npm warn" | tail -40; rm -f src/smoke.test.tsx; git status --short

